///|
test "SGA calls distinguish producer references ID values and column designations" {
  let reach = parse_sga_call(
    "reach(start: {from: `seed rows`, id: \"node key\"}, direction: 'out', max_depth: 2)",
    query_limits(),
  ).unwrap()
  assert_eq(reach.operation, "reach")
  assert_eq(reach.arguments, [
    (
      "start",
      ObjectValue([
        ("from", Producer({ value: "seed rows", quoted: true, })),
        ("id", TextValue("node key")),
      ]),
    ),
    ("direction", TextValue("out")),
    ("max_depth", NumberValue("2")),
  ])
  let single = parse_sga_call("reach(start: 'A')", query_limits()).unwrap()
  assert_eq(single.arguments, [("start", TextValue("A"))])
  let apply = parse_sga_call(
    "apply_graph_delta(with: changes, field: 'delta')",
    query_limits(),
  ).unwrap()
  assert_eq(apply.arguments, [
    ("with", Producer({ value: "changes", quoted: false, })),
    ("field", TextValue("delta")),
  ])
}

///|
test "SGA explicit Graph lists never add an implicit current producer" {
  let call = parse_sga_call(
    "mean_graphs(with: [first, `second graph`], weights: [1, 2])",
    query_limits(),
  ).unwrap()
  assert_eq(call.arguments, [
    (
      "with",
      ListValue([
        Producer({ value: "first", quoted: false, }),
        Producer({ value: "second graph", quoted: true, }),
      ]),
    ),
    ("weights", ListValue([NumberValue("1"), NumberValue("2")])),
  ])
}

///|
test "SGA uses the complete adopted closed operation vocabulary" {
  for
    operation in [
      "reach", "traverse", "shortest_path", "components", "degree", "graph_bounds",
      "match_nodes", "match_edges", "normalize_graph", "subgraph", "graft_graph",
      "union_graphs", "subtract_graphs", "graphs_equal", "graph_diff", "apply_graph_delta",
      "mean_graphs", "node_rows", "edge_rows",
    ] {
    assert_eq(
      parse_sga_call(operation + "()", query_limits()).unwrap().operation,
      operation,
    )
  }
  assert_eq(
    parse_sga_call("COMPONENTS(KIND: 'weak')", query_limits()).unwrap().arguments,
    [("kind", TextValue("weak"))],
  )
}

///|
test "SGA rejects string producer references duplicate arguments and malformed calls" {
  for
    text in [
      "reach(start: {from: 'seeds', id: 'id'})", "traverse(start: {from: \"seeds\", id: 'id'})",
      "shortest_path(source: {from: 'seeds'})", "shortest_path(target: {from: 'seeds'})",
      "subgraph(nodes: {from: 'selected'})", "graphs_equal(with: 'peer')", "mean_graphs(with: [first, 'second'])",
      "reach(start: {from: seeds, FROM: other})", "components(kind: 'weak', KIND: 'strong')",
      "components(kind: weak)", "`components`(kind: 'weak')", "another_graph_algorithm()",
      "OP reach {}", "normalize_graph() trailing", "mean_graphs(with: [first,])",
      "components(kind: 'weak',)", "reach(start: {from: seeds,})",
    ] {
    assert_true(parse_sga_call(text, query_limits()) is Err(_), msg=text)
  }
}

///|
test "SGA preserves decoded strings and exact numeric spelling" {
  let call = parse_sga_call(
    "reach(start: \"e\\u0301\\r\", max_depth: 9007199254740993, max_output_rows: @bound)",
    query_limits(),
  ).unwrap()
  assert_eq(call.arguments, [
    ("start", TextValue("e\u0301\r")),
    ("max_depth", NumberValue("9007199254740993")),
    ("max_output_rows", ParameterValue("bound")),
  ])
  // Syntax does not round a numeric token or validate its operation-specific
  // range. Ordinary lowering/admission/checking still owns those obligations.
  assert_eq(
    parse_sga_call("reach(start: r'A\\n' 'B')", query_limits()).unwrap().arguments,
    [("start", TextValue("A\\nB"))],
  )
  let literal = parse_sga_call(
    "match_nodes(where: {eq: [{literal: {Name: 'x', name: 'y'}}, null]})",
    query_limits(),
  ).unwrap()
  assert_eq(literal.arguments, [
    (
      "where",
      ObjectValue([
        (
          "eq",
          ListValue([
            ObjectValue([
              (
                "literal",
                ObjectValue([("Name", TextValue("x")), ("name", TextValue("y"))]),
              ),
            ]),
            NullValue,
          ]),
        ),
      ]),
    ),
  ])
}

///|
test "SGA parser shares work node depth and original source position limits" {
  let text = "--😀\r\nreach(start: {from: seeds, id: 'id'})"
  let call = parse_sga_call(text, query_limits()).unwrap()
  assert_eq(call.start, 8)
  assert_eq(call.end, text.length() + 2)
  assert_true(
    parse_sga_call(text, { ..query_limits(), max_syntax_nodes: 1, }) is Err(_),
  )
  assert_true(
    parse_sga_call(text, { ..query_limits(), max_work: 1, }) is Err(_),
  )
  assert_true(
    parse_sga_call(text, {
      ..query_limits(),
      expression: { ..query_limits().expression, max_depth: 0, },
    })
    is Err(_),
  )
  let bad = parse_sga_call(
    "--😀\r\nreach(start: {from: 'seeds'})",
    query_limits(),
    source_path="bad-sga.aql",
  ).unwrap_err().span.unwrap()
  assert_eq(bad.source_path, "bad-sga.aql")
  assert_eq(bad.start_line, 2)
  assert_eq(bad.start_column, 21)
  let nested = StringBuilder()
  nested.write_string("match_nodes(where: ")
  for _ in 0..<33 {
    nested.write_string("[")
  }
  nested.write_string("true")
  for _ in 0..<33 {
    nested.write_string("]")
  }
  nested.write_string(")")
  assert_true(
    parse_sga_call(nested.to_string(), {
      ..query_limits(),
      expression: { ..query_limits().expression, max_depth: 128, },
    })
    is Err(_),
  )
  for invalid in [-1, 2147483647] {
    assert_true(
      parse_sga_call("normalize_graph()", {
        ..query_limits(),
        max_syntax_nodes: invalid,
      })
      is Err({ issue: InvalidLimits, .. }),
    )
  }
}

///|
test "SGA query and WITH composition share their original token stream" {
  let script = parse_query_script(
    "WITH averaged AS (mean_graphs(with: [first, second])), normalized AS (FROM averaged |> normalize_graph()) FROM GRAPH normalized |> normalize_graph() |> MATCH WALK (a:Node) |> SELECT a.id",
    query_limits(),
  ).unwrap()
  assert_true(
    producer_primary(query_binding_at(script_query(script), 0).unwrap().query)
    is Some(GraphGenerator(_)),
  )
  let body = query_binding_at(script_query(script), 1).unwrap().query
  assert_true(operation_at(body, 0) is Some(GraphCall(_)))
  assert_eq(operation_count(after_graph_calls(body)), 0)
  let terminal = script_query(script)
  assert_true(operation_at(terminal, 0) is Some(GraphCall(_)))
  assert_true(
    operation_at(after_graph_calls(terminal), 0) is Some(Select(_, _)),
  )
  assert_true(graph_query(after_graph_calls(terminal)) is Some(_))
}

///|
test "SGA call accessors preserve parsed nested arguments after caller mutation" {
  let query = parse_query(
    "FROM first |> mean_graphs(with: [first, second])",
    query_limits(),
  ).unwrap()
  guard operation_at(query, 0) is Some(GraphCall(call)) &&
    call.arguments[0].1 is ListValue(items) else {
    fail("expected a Graph list")
  }
  items.clear()
  call.arguments.clear()
  guard operation_at(query, 0) is Some(GraphCall(original)) &&
    original.arguments[0].1 is ListValue(retained) else {
    fail("expected retained original arguments")
  }
  assert_eq(retained.length(), 2)
  assert_true(
    parse_query(
      "FROM GRAPH g |> MATCH WALK (a) |> normalize_graph()",
      query_limits(),
    )
    is Err(_),
  )
}

///|
// Seed admitted lexical coordinates independently of parser-generated names.
// These controls exercise reference roles, not Carrier admission or execution.
fn producer_scope_parser(text : String) -> QueryParser {
  let lexical : LexicalLimits = {
    max_source_bytes: 10000,
    max_tokens: 1000,
    max_literal_bytes: 10000,
    max_work: 20000,
  }
  let limits : QueryLimits = {
    lexical,
    expression: { lexical, max_nodes: 1000, max_depth: 100, max_work: 10000, },
    max_syntax_nodes: 100,
    max_cte_count: 20,
    max_work: 10000,
  }
  let source = tokenize(text, lexical, source_path="producer-scope.sql").unwrap()
  {
    source,
    limits,
    index: 0,
    work: 0,
    expression_nodes: 0,
    syntax_nodes: 0,
    source_depth: 0,
    synthetic_sources: 0,
    binding_scopes: [
      [
        (
          { value: "rows", quoted: false, },
          { value: "outer_rows", quoted: false, },
        ),
        (
          { value: "peer", quoted: false, },
          { value: "outer_peer", quoted: false, },
        ),
      ],
      [
        (
          { value: "rows", quoted: false, },
          { value: "inner_rows", quoted: false, },
        ),
      ],
    ],
  }
}

///|
test "Graph mapping resolves nearest producer without renaming definitions" {
  let parser = producer_scope_parser(
    "GRAPH (NODE TABLES (`ROWS` KEY (id) LABEL rows NO PROPERTIES) EDGE TABLES (catalog.edges AS E KEY (edge_id) SOURCE KEY (src) REFERENCES `ROWS` DESTINATION KEY (dst) REFERENCES `ROWS` LABEL R NO PROPERTIES))",
  )
  let mapping = parser.graph()
  parser.end()
  assert_eq(mapping.nodes[0].producer, [{ value: "inner_rows", quoted: false, }])
  assert_eq(mapping.nodes[0].name, { value: "ROWS", quoted: true, })
  assert_eq(mapping.nodes[0].labels[0].name, { value: "rows", quoted: false, })
  assert_eq(mapping.edges[0].producer, [
    { value: "catalog", quoted: false, },
    { value: "edges", quoted: false, },
  ])
  assert_eq(mapping.edges[0].source.definition, { value: "ROWS", quoted: true, })
  assert_eq(mapping.edges[0].destination.definition, {
    value: "ROWS",
    quoted: true,
  })
}

///|
test "SGA producer roles resolve scope while ID and field values remain data" {
  let parser = producer_scope_parser(
    "reach(start: {from: `ROWS`, id: 'rows'}, direction: 'out', max_depth: 2)",
  )
  let call = parser.sga_call()
  parser.end()
  assert_eq(call.arguments, [
    (
      "start",
      ObjectValue([
        ("from", Producer({ value: "inner_rows", quoted: false, })),
        ("id", TextValue("rows")),
      ]),
    ),
    ("direction", TextValue("out")),
    ("max_depth", NumberValue("2")),
  ])
  let list_parser = producer_scope_parser(
    "mean_graphs(with: [ROWS, peer], weights: [1, 2])",
  )
  let list = list_parser.sga_call()
  list_parser.end()
  assert_eq(list.arguments, [
    (
      "with",
      ListValue([
        Producer({ value: "inner_rows", quoted: false, }),
        Producer({ value: "outer_peer", quoted: false, }),
      ]),
    ),
    ("weights", ListValue([NumberValue("1"), NumberValue("2")])),
  ])
  let id_parser = producer_scope_parser("reach(start: 'rows')")
  assert_eq(id_parser.sga_call().arguments, [("start", TextValue("rows"))])
  id_parser.end()
}

///|
test "FROM GRAPH resolves the nearest binding before any Carrier check" {
  let parser = producer_scope_parser(
    "FROM GRAPH `ROWS` |> MATCH WALK (a) |> SELECT a.id",
  )
  let query = parser.query()
  parser.end()
  assert_eq(relation(query), [{ value: "inner_rows", quoted: false, }])
  assert_eq(relation_alias(query), None)
  assert_true(graph_query(query) is Some(_))
  assert_eq(parser.binding_scopes.length(), 2)
  // Resolving does not search an outer Graph to repair a nearer type mismatch.
  // The common checker, not this parser, decides that Carrier validity.
  assert_eq(parser.resolve_producer([{ value: "rows", quoted: false, }]), [
    { value: "inner_rows", quoted: false, },
  ])
}

///|
test "Graph match binding vocabulary folds without rewriting output names" {
  let call = parse_sga_call(
    "MATCH_EDGES(BINDINGS: {IDENTITY: 'Edge', `Source`: 'Source', TARGET: 'Target'})",
    query_limits(),
  ).unwrap()
  assert_eq(call.arguments, [
    (
      "bindings",
      ObjectValue([
        ("identity", TextValue("Edge")),
        ("source", TextValue("Source")),
        ("target", TextValue("Target")),
      ]),
    ),
  ])
}

///|
test "Graph match duplicate binding roles reject after folding" {
  for
    text in [
      "match_nodes(bindings: {identity: 'first', IDENTITY: 'second'})", "match_edges(bindings: {source: 'first', `Source`: 'second'})",
    ] {
    assert_true(
      parse_sga_call(text, query_limits())
      is Err({ issue: Syntax("Duplicate SGA argument"), .. }),
      msg=text,
    )
  }
}

///|
test "Graph match bindings do not fold unrelated literal property data" {
  let call = parse_sga_call(
    "match_nodes(bindings: {identity: 'Element'}, where: {eq: [{literal: {Identity: 'e\\u0301\\r', identity: 'x'}}, null]})",
    query_limits(),
  ).unwrap()
  guard call.arguments[1].1
    is ObjectValue(
      [(_, ListValue([ObjectValue([(_, ObjectValue(fields))]), _]))]
    ) else {
    fail("expected an unchanged literal object")
  }
  assert_eq(fields, [
    ("Identity", TextValue("e\u0301\r")),
    ("identity", TextValue("x")),
  ])
}

///|
test "traverse hop vocabulary folds while predicate data retains its spelling" {
  let actual = parse_sga_call(
    "TRAVERSE(START: {FROM: seeds, ID: 'element'}, HOPS: [{DIRECTION: 'out', EDGE_TYPES: [], NODE_WHERE: {eq: [{literal: {Direction: 'e\\u0301\\r', direction: 'x'}}, null]}}], EMIT: 'nodes')",
    query_limits(),
  ).unwrap()
  let expected = parse_sga_call(
    "traverse(start: {from: seeds, id: 'element'}, hops: [{direction: 'out', edge_types: [], node_where: {eq: [{literal: {Direction: 'e\\u0301\\r', direction: 'x'}}, null]}}], emit: 'nodes')",
    query_limits(),
  ).unwrap()
  assert_eq(actual.arguments, expected.arguments)
  guard actual.arguments[1].1 is ListValue([ObjectValue(fields)]) else {
    fail("expected a single typed hop")
  }
  assert_true(fields.contains(("direction", TextValue("out"))))
  guard fields[2].1
    is ObjectValue([(_, ListValue([ObjectValue([(_, ObjectValue(data))]), _]))]) else {
    fail("expected the unchanged literal object")
  }
  assert_eq(data, [
    ("Direction", TextValue("e\u0301\r")),
    ("direction", TextValue("x")),
  ])
}

///|
test "traverse duplicate hop vocabulary is rejected after name folding" {
  for
    text in [
      "traverse(hops: [{direction: 'out', DIRECTION: 'in'}])", "traverse(hops: [{edge_types: [], `EDGE_TYPES`: ['R']}])",
      "traverse(hops: [{node_where: true, NODE_WHERE: false}])",
    ] {
    assert_true(
      parse_sga_call(text, query_limits())
      is Err({ issue: Syntax("Duplicate SGA argument"), .. }),
      msg=text,
    )
  }
}
